import axios from 'axios';
import React, { useEffect, useState } from 'react'
import { useNavigate } from 'react-router-dom';


import { Property } from '../../../types/property';
import { BASE_URL } from '../../../utils/requests';
import {DetailWrapper,Detailgrid,DetailsContainer,TitleContainer} from './styles';

type Props = {
    propertyId : string;
}




const PropertyDetails = ({propertyId}: Props)=>{

    const navigate= useNavigate();

    const [property, setProperty] = useState<Property>();

    useEffect(() =>{
        axios.get(`${BASE_URL}/movies/${propertyId}`)
             .then(Response => {
                 setProperty(Response.data);
             });
    }, [propertyId]);
    
    return(
        <DetailWrapper>
            <TitleContainer>
            <h1>Casa a venda nos estados unidos</h1>
            </TitleContainer>
            <DetailsContainer>
            <h2>R$200000</h2>
                  <p>Este imovel se encontra no estado do arkansas, ao centro dos estados unidos
                      situado em uma região de otima qualidade, perto de escolas, predios,
                      batante verde.
                  </p>
                  
            <h3>Detail</h3>
            <Detailgrid>
                <div>
                    <h4>Price</h4>
                    <span>valor</span>
                </div>
                <div>
                    <h4>Title</h4>
                    <span>valor</span>
                </div>
                <div>
                    <h4>Title</h4>
                    <span>valor</span>
                </div>
                <div>
                    <h4>Title</h4>
                    <span>valor</span>
                </div>
            </Detailgrid>
            </DetailsContainer>
        </DetailWrapper>
    )
}

export default PropertyDetails
